  const GLYPHS = [
    { name: 'Circular A12', fill: FILL_1, wires: [WIRE_1_SW0, WIRE_1_SW1, WIRE_1_SW2] },
  { name: 'Circular A3', fill: FILL_2, wires: [WIRE_2_SW0, WIRE_2_SW1, WIRE_2_SW2] },
  { name: 'Circular A5', fill: FILL_3, wires: [WIRE_3_SW0, WIRE_3_SW1, WIRE_3_SW2] },
  { name: 'Circular A24', fill: FILL_4, wires: [WIRE_4_SW0, WIRE_4_SW1, WIRE_4_SW2] },
  ];

  const SW_LABELS = ['0.4 — sutil', '0.8 — medio', '1.4 — marcado'];

  export function WireframeMosaico() {
    const [swIdx, setSwIdx] = useState(1);
    const [mode, setMode] = useState<'compare' | 'wireframe' | 'fill'>('compare');

    return (
      <div style={{ minHeight: '100vh', background: '#1B060F', display: 'flex', flexDirection: 'column', alignItems: 'center', justifyContent: 'center', padding: '36px 32px', gap: 32, fontFamily: 'system-ui' }}>

        {/* Header */}
        <div style={{ textAlign: 'center' }}>
          <div style={{ color: '#D4AF37', fontSize: 15, fontWeight: 700, letterSpacing: '0.1em', textTransform: 'uppercase' }}>
            Mosaico Wireframe
          </div>
          <div style={{ color: 'rgba(244,218,213,0.45)', fontSize: 12, marginTop: 4 }}>
            Mosaicos de relleno → versión trazo vacío
          </div>
        </div>

        {/* Controles */}
        <div style={{ display: 'flex', gap: 24, alignItems: 'center', flexWrap: 'wrap', justifyContent: 'center' }}>
          {/* Modo */}
          <div style={{ display: 'flex', background: 'rgba(74,12,12,0.4)', borderRadius: 8, overflow: 'hidden', border: '1px solid rgba(212,175,55,0.15)' }}>
            {(['compare', 'wireframe', 'fill'] as const).map(m => (
              <button key={m} onClick={() => setMode(m)} style={{
                padding: '6px 14px', fontSize: 11, fontWeight: 600, letterSpacing: '0.06em',
                textTransform: 'uppercase', border: 'none', cursor: 'pointer', transition: 'all 0.15s',
                background: mode === m ? 'rgba(212,175,55,0.2)' : 'transparent',
                color: mode === m ? '#D4AF37' : 'rgba(244,218,213,0.4)',
              }}>
                {m === 'compare' ? 'Comparar' : m === 'wireframe' ? 'Solo wireframe' : 'Solo relleno'}
              </button>
            ))}
          </div>

          {/* Stroke width selector (solo activo en wireframe o compare) */}
          {mode !== 'fill' && (
            <div style={{ display: 'flex', gap: 8, alignItems: 'center' }}>
              <span style={{ color: 'rgba(212,175,55,0.5)', fontSize: 10, letterSpacing: '0.1em', textTransform: 'uppercase' }}>Trazo</span>
              {SW_LABELS.map((label, i) => (
                <button key={i} onClick={() => setSwIdx(i)} style={{
                  padding: '5px 10px', fontSize: 11, borderRadius: 6, border: '1px solid',
                  cursor: 'pointer', transition: 'all 0.15s',
                  borderColor: swIdx === i ? '#D4AF37' : 'rgba(212,175,55,0.2)',
                  background: swIdx === i ? 'rgba(212,175,55,0.15)' : 'transparent',
                  color: swIdx === i ? '#D4AF37' : 'rgba(244,218,213,0.4)',
                }}>
                  {label}
                </button>
              ))}
            </div>
          )}
        </div>

        {/* Grid de glifos */}
        <div style={{ display: 'flex', gap: 0, width: '100%' }}>
          {GLYPHS.map((g, i) => (
            <div key={i} style={{
              flex: 1, display: 'flex', flexDirection: 'column', alignItems: 'center', gap: 8,
              padding: '0 16px',
              borderRight: i < GLYPHS.length - 1 ? '1px solid rgba(212,175,55,0.08)' : 'none'
            }}>
              {mode === 'compare' ? (
                /* Comparación: fill arriba, wireframe abajo */
                <div style={{ display: 'flex', gap: 12, alignItems: 'center' }}>
                  <div style={{ display: 'flex', flexDirection: 'column', alignItems: 'center', gap: 4 }}>
                    <svg viewBox="0 0 85.4 85.4" width={150} height={150} style={{ overflow: 'visible' }}
                      dangerouslySetInnerHTML={{ __html: g.fill }} />
                    <span style={{ color: 'rgba(244,218,213,0.3)', fontSize: 9, letterSpacing: '0.08em', textTransform: 'uppercase' }}>relleno</span>
                  </div>
                  <div style={{ color: 'rgba(212,175,55,0.3)', fontSize: 18 }}>→</div>
                  <div style={{ display: 'flex', flexDirection: 'column', alignItems: 'center', gap: 4 }}>
                    <svg viewBox="0 0 85.4 85.4" width={150} height={150} style={{ overflow: 'visible' }}
                      dangerouslySetInnerHTML={{ __html: g.wires[swIdx] }} />
                    <span style={{ color: 'rgba(244,218,213,0.3)', fontSize: 9, letterSpacing: '0.08em', textTransform: 'uppercase' }}>wireframe</span>
                  </div>
                </div>
              ) : (
                <svg viewBox="0 0 85.4 85.4" width={200} height={200} style={{ overflow: 'visible' }}
                  dangerouslySetInnerHTML={{ __html: mode === 'wireframe' ? g.wires[swIdx] : g.fill }} />
              )}
              <div style={{ textAlign: 'center', marginTop: 4 }}>
                <div style={{ color: '#D4AF37', fontSize: 12, fontWeight: 600 }}>{g.name}</div>
              </div>
            </div>
          ))}
        </div>

        {/* Nota */}
        <div style={{ color: 'rgba(244,218,213,0.25)', fontSize: 10, textAlign: 'center', maxWidth: 600, lineHeight: 1.6 }}>
          Wireframe = fill:"none" + stroke por path. Sin cambios en GLYPH_STRINGS existentes — serían entradas nuevas. Compatible con outlineWidth actual (el borde exterior se suma al trazo interno).
        </div>
      </div>
    );
  }

  export default WireframeMosaico;
  